// Generated by `just generate` from `src/plugins/dotclaude-sessions/slices/usage/domain/parse.ts`. Edit the source and run `just generate`.
// Helpers for the usage report: call prices, transcript parsing, and counts.

import { rethrowUnless } from "../../../kernel/errors.ts";
import { parseModel } from "../../../kernel/model.ts";
import type { Store } from "../ports.ts";
import type {
  Block,
  BriefSize,
  BriefStat,
  CallCost,
  Entry,
  LimitedRun,
  MessageUsage,
  Usage,
} from "./types.ts";

// $ per million tokens: input, output, cache read, 5m write, 1h write.
type Prices = [number, number, number, number, number];
const FABLE_5_1: Prices = [10, 50, 0.25, 12.5, 20];
const FABLE_5: Prices = [10, 50, 1, 12.5, 20];
const OPUS_4_5: Prices = [5, 25, 0.5, 6.25, 10];
const OPUS_4: Prices = [15, 75, 1.5, 18.75, 30];
const SONNET_4: Prices = [3, 15, 0.3, 3.75, 6];
// The prices of the pricing page, https://platform.claude.com/docs/en/about-claude/pricing, on 2026-10-13.
// A version that is not here gets the prices of the newest version of its family.
const PRICES: Record<string, Record<string, Prices>> = {
  fable: { "5.1": FABLE_5_1, "5": FABLE_5 },
  mythos: { "5.1": FABLE_5_1, "5": FABLE_5 },
  opus: {
    "5.5": [4, 20, 0.2, 5, 8],
    "5": OPUS_4_5,
    "4.8": OPUS_4_5,
    "4.7": OPUS_4_5,
    "4.6": OPUS_4_5,
    "4.5": OPUS_4_5,
    "4.1": OPUS_4,
    "4": OPUS_4,
  },
  sonnet: {
    "5.5": [2, 10, 0.1, 2.5, 4],
    "5": [2, 10, 0.2, 2.5, 4],
    "4.6": SONNET_4,
    "4.5": SONNET_4,
    "4": SONNET_4,
  },
  haiku: {
    "5.5": [0.1, 0.5, 0.01, 0.125, 0.2],
    "4.5": [1, 5, 0.1, 1.25, 2],
  },
};
// A Haiku 5.5 call whose prompt, with its cache reads and writes, is over 100,000 tokens pays these prices.
const HAIKU_5_5_LONG: Prices = [0.5, 2.5, 0.05, 0.625, 1];
const HAIKU_5_5_PROMPT = 100_000;

const pricesOf = (model: unknown, prompt: number): Prices | undefined => {
  const id = parseModel(model);
  const versions = id && PRICES[id.family];
  if (!(id && versions)) return;
  const version = id.minor === null ? `${id.major}` : `${id.major}.${id.minor}`;
  if (version === "5.5" && id.family === "haiku" && prompt > HAIKU_5_5_PROMPT)
    return HAIKU_5_5_LONG;
  const newest = Object.keys(versions).sort((a, b) => Number(b) - Number(a));
  return versions[version] ?? versions[newest[0] as string];
};

export const callCost = (model: unknown, u: Usage): CallCost => {
  const read = u.cache_read_input_tokens ?? 0;
  const input = u.input_tokens ?? 0;
  const prices = pricesOf(
    model,
    input + read + (u.cache_creation_input_tokens ?? 0),
  );
  if (!prices) return { total: 0, write: 0, context: 0, read: 0 };
  const [pi, po, pr, p5, p1] = prices;
  const cc = u.cache_creation;
  const w1 = cc?.ephemeral_1h_input_tokens ?? 0;
  const w5 = cc
    ? (cc.ephemeral_5m_input_tokens ?? 0)
    : (u.cache_creation_input_tokens ?? 0);
  const write = (w5 * p5 + w1 * p1) / 1e6;
  return {
    total: (input * pi + (u.output_tokens ?? 0) * po + read * pr) / 1e6 + write,
    write,
    context: input + read + (u.cache_creation_input_tokens ?? 0),
    read,
    rewrite:
      (u.cache_creation_input_tokens ?? 0) > 30_000 &&
      (u.cache_creation_input_tokens ?? 0) > read,
  };
};

// The context window in tokens: 1M for a model name that marks a 1M window, else 200k.
export const windowOf = (model: unknown): number =>
  /\[1m\]|-1m\b/i.test(String(model)) ? 1_000_000 : 200_000;

// A source or config file that a brief names, with or without a directory.
const FILE =
  /(?:[\w.@-]+\/)*[\w.@-]+\.(?:mjs|cjs|js|jsx|ts|tsx|py|go|rs|rb|java|kt|swift|c|h|cc|cpp|hpp|cs|php|md|json|jsonc|yaml|yml|toml|sh|sql|css|scss|html|vue|svelte)\b/g;

// A bulleted or numbered line: one item of work, a constraint, or a check.
const ITEM = /^\s*(?:[-*+]|\d+[.)])\s/gm;

/** The fields of a transcript row that `briefSize` reads. */
type Row = {
  type?: string;
  message?: { content?: string | { text?: string }[] };
};

/** The files and list items of the first user prompt of the transcript `file`. */
export const briefSize = async (
  store: Store,
  file: string,
): Promise<BriefSize> => {
  for (const line of ((await store.read(file)) ?? "").split("\n")) {
    let entry: Row | null;
    try {
      entry = JSON.parse(line);
    } catch (err) {
      rethrowUnless(err, "SyntaxError");
      continue;
    }
    if (entry === null || typeof entry !== "object") continue;
    if (entry.type !== "user") continue;
    const c = entry.message?.content;
    const text = (
      typeof c === "string"
        ? c
        : (Array.isArray(c) ? c : []).map((b) => b.text ?? "").join("\n")
    ).replace(/\w+:\/\/\S+/g, "");
    return {
      files: new Set(text.match(FILE) ?? []).size,
      items: (text.match(ITEM) ?? []).length,
    };
  }
  return { files: 0, items: 0 };
};

// Claude Code writes a message's usage once per content block. The first
// record is the stream start, with an output count near zero, so each
// message counts the record with the largest output. Subagent transcripts
// often keep no final record, so that count is a lower bound.
export const bestUsage = (
  entries: Entry[],
): Map<string | undefined, MessageUsage> => {
  const best = new Map<string | undefined, MessageUsage>();
  for (const e of entries) {
    const u = e.type === "assistant" && e.message?.usage;
    if (!u) continue;
    const b = best.get(e.message?.id);
    if (!b || (u.output_tokens ?? 0) > (b.usage.output_tokens ?? 0))
      best.set(e.message?.id, { usage: u, final: b?.final });
    if (e.message?.stop_reason)
      (best.get(e.message?.id) as MessageUsage).final = true;
  }
  return best;
};

export const median = (xs: number[]): number => {
  const s = [...xs].sort((a, b) => a - b);
  return s.length ? (s[Math.floor((s.length - 1) / 2)] as number) : 0;
};

// The `q` quantile of `xs`, by the nearest rank.
export const quantile = (xs: number[], q: number): number => {
  const s = [...xs].sort((a, b) => a - b);
  return s.length ? (s[Math.max(0, Math.ceil(q * s.length) - 1)] as number) : 0;
};

export const resultText = (c: unknown): string =>
  typeof c === "string"
    ? c
    : (Array.isArray(c) ? (c as Block[]) : [])
        .map((b) => b.text ?? "")
        .join("\n");

/** The first line of `text`, cut to about 80 characters. */
export const firstLine = (text: unknown): string => {
  const line =
    String(text ?? "")
      .split("\n")
      .find((l) => l.trim() && !l.startsWith("agentId:")) ?? "";
  const t = line.trim();
  return t.length > 80 ? `${t.slice(0, 79)}…` : t;
};

/** Per agent type: runs, and the median files and list items in the brief. */
export const briefStats = (runs: LimitedRun[]): BriefStat[] => {
  const byType = new Map<string, LimitedRun[]>();
  for (const r of runs) {
    const rs = byType.get(r.type);
    if (rs) rs.push(r);
    else byType.set(r.type, [r]);
  }
  return [...byType]
    .map(([type, rs]) => ({
      type,
      runs: rs.length,
      files: median(rs.map((r) => r.files)),
      items: median(rs.map((r) => r.items)),
    }))
    .sort((a, b) => b.runs - a.runs);
};

/** Estimated tokens: the larger of chars / 4 and words / 0.75. */
export const tokens = (text: string): number => {
  const words = text.split(/\s+/).filter(Boolean).length;
  return Math.max(Math.ceil([...text].length / 4), Math.ceil(words / 0.75));
};
